const resolveUserParameterMapping = `-- name: ResolveUserParameterMapping :one
WITH sibling AS (
    SELECT pp.parameter_id
    FROM part_parameters pp
    WHERE pp.part_id = $2
      AND pp.name = $1
      AND pp.source_type = 'distributor'
      AND pp.parameter_id IS NOT NULL
    LIMIT 1
)
SELECT pd.id, pd.value_type
FROM parameter_definitions pd
WHERE pd.id = (SELECT parameter_id FROM sibling)
   OR pd.slug = $1
   OR lower(pd.display_name) = lower($1)
ORDER BY (pd.id = (SELECT parameter_id FROM sibling)) DESC NULLS LAST, pd.id
LIMIT 1
`

type ResolveUserParameterMappingParams struct {
	Name   string      `json:"name"`
	PartID pgtype.UUID `json:"part_id"`
}

type ResolveUserParameterMappingRow struct {
	ID        int32  `json:"id"`
	ValueType string `json:"value_type"`
}

// Resolves the canonical parameter definition for a user-specified parameter on a
// part, so user-entered values (new params and overrides of distributor values)
// can carry a parameter_id + parsed numeric_value and thus appear in the list-view
// parameter columns and participate in value search. Preference order:
//  1. Inherit the mapping of an existing distributor-sourced parameter on this
//     part with the same name — the override case (the edit UI reuses the
//     distributor param's raw name, so this matches reliably).
//  2. Otherwise match the registry directly by slug or case-insensitive display
//     name, covering manually-entered parts that have no distributor sibling.
//
// Returns no rows when the name maps to no canonical parameter, in which case the
// caller leaves parameter_id NULL (today's free-text behaviour).
func (q *Queries) ResolveUserParameterMapping(ctx context.Context, arg ResolveUserParameterMappingParams) (ResolveUserParameterMappingRow, error) {
	row := q.db.QueryRow(ctx, resolveUserParameterMapping, arg.Name, arg.PartID)
	var i ResolveUserParameterMappingRow
	err := row.Scan(&i.ID, &i.ValueType)
	return i, err
}

const setPartEnriched = `-- name: SetPartEnriched :exec
UPDATE parts
SET enrichment_source_id = $2,
    enriched_at          = NOW(),
    lifecycle_status     = COALESCE($3::part_lifecycle_status, lifecycle_status),
    mpn                  = COALESCE($4, mpn),
    description          = COALESCE($5, description),
    datasheet_url        = COALESCE($6, datasheet_url),
    short_description    = COALESCE($7, short_description),
    product_url          = COALESCE($8, product_url),
    image_url            = COALESCE($9, image_url),
    package              = COALESCE($10, package),
    canonical_package    = COALESCE($11, canonical_package),
    category_id          = CASE
                               WHEN category_source = 'auto' AND $12::int IS NOT NULL
                               THEN $12::int
                               ELSE category_id
                           END
WHERE id = $1
`

type SetPartEnrichedParams struct {
	ID                 pgtype.UUID             `json:"id"`
	EnrichmentSourceID pgtype.UUID             `json:"enrichment_source_id"`
	LifecycleStatus    NullPartLifecycleStatus `json:"lifecycle_status"`
	Mpn                *string                 `json:"mpn"`
	Description        *string                 `json:"description"`
	DatasheetUrl       *string                 `json:"datasheet_url"`
	ShortDescription   *string                 `json:"short_description"`
	ProductUrl         *string                 `json:"product_url"`
	ImageUrl           *string                 `json:"image_url"`
	Package            *string                 `json:"package"`
	CanonicalPackage   *string                 `json:"canonical_package"`
	NewCategoryID      *int32                  `json:"new_category_id"`
}

// Records which distributor last enriched this part, when, and updates all enrichable
// fields. NULL keeps existing values (COALESCE pattern).
// canonical_package is derived from the raw package by the caller (genspec.NormalizePackage);
// both follow the same COALESCE rule so re-enrichment keeps parametric matching working.
// category_id is only updated when the part's category_source is 'auto' and a non-NULL
// new_category_id is provided; user-assigned categories are never overwritten by enrichment.
func (q *Queries) SetPartEnriched(ctx context.Context, arg SetPartEnrichedParams) error {
	_, err := q.db.Exec(ctx, setPartEnriched,
		arg.ID,
		arg.EnrichmentSourceID,
		arg.LifecycleStatus,
		arg.Mpn,
		arg.Description,
		arg.DatasheetUrl,
		arg.ShortDescription,
		arg.ProductUrl,
		arg.ImageUrl,
		arg.Package,
		arg.CanonicalPackage,
		arg.NewCategoryID,
	)
	return err
}

const setPartParameterParsed = `-- name: SetPartParameterParsed :exec
UPDATE part_parameters SET numeric_value = $2, numeric_value_max = $3, enum_values = $4 WHERE id = $1
`

type SetPartParameterParsedParams struct {
	ID              pgtype.UUID `json:"id"`
	NumericValue    *float64    `json:"numeric_value"`
	NumericValueMax *float64    `json:"numeric_value_max"`
	EnumValues      []string    `json:"enum_values"`
}

// Overwrites the parsed representation of a single part parameter row (numeric for
// numeric/range parameters, enum_values for enum_set; the unused ones are NULL).
func (q *Queries) SetPartParameterParsed(ctx context.Context, arg SetPartParameterParsedParams) error {
	_, err := q.db.Exec(ctx, setPartParameterParsed,
		arg.ID,
		arg.NumericValue,
		arg.NumericValueMax,
		arg.EnumValues,
	)
	return err
}

